namespace Folha {
static class J {
 public static JavaScriptSerializer Serializer(){return new JavaScriptSerializer{MaxJsonLength=64*1024*1024,RecursionLimit=128};}
 public static string Encode(object x){return Serializer().Serialize(x);}
 public static Dictionary<string,object> Parse(string x){return Serializer().Deserialize<Dictionary<string,object>>(x);}
 public static Dictionary<string,object> Obj(object x){return (Dictionary<string,object>)x;}
 public static string S(Dictionary<string,object> x,string k,string def=""){object v;return x.TryGetValue(k,out v)&&v!=null?Convert.ToString(v,System.Globalization.CultureInfo.InvariantCulture):def;}
 public static int I(Dictionary<string,object>x,string k,int def=0){object v;return x.TryGetValue(k,out v)?Convert.ToInt32(v):def;}
 public static IEnumerable<object> List(object x){return ((IEnumerable)x).Cast<object>();}
 public static string Hash(byte[] b){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(b)).Replace("-","").ToLowerInvariant();}
 public static string HashFile(string f){using(var h=SHA256.Create())using(var s=File.OpenRead(f))return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 public static long Now(){return DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();}
 public static string Id(){return Guid.NewGuid().ToString();}
 public static bool ValidId(string s){Guid g;return Guid.TryParseExact(s,"D",out g);}
 public static void Atomic(string f,string text){Directory.CreateDirectory(Path.GetDirectoryName(f));var t=f+".tmp";using(var s=new FileStream(t,FileMode.Create,FileAccess.Write,FileShare.None)){var b=Encoding.UTF8.GetBytes(text);s.Write(b,0,b.Length);s.Flush(true);}if(File.Exists(f))File.Replace(t,f,f+".bak",true);else File.Move(t,f);}
 public static object Sorted(object v){var d=v as Dictionary<string,object>;if(d!=null){var r=new SortedDictionary<string,object>(StringComparer.Ordinal);foreach(var p in d)if(p.Key!="revision"&&p.Key!="updated"&&p.Key!="lastPage"&&p.Key!="lastOpened")r[p.Key]=Sorted(p.Value);return r;}if(v is IEnumerable && !(v is string))return ((IEnumerable)v).Cast<object>().Select(Sorted).ToArray();return v;}
 public static string Fingerprint(Dictionary<string,object>d){return Hash(Encoding.UTF8.GetBytes(Encode(Sorted(d))));}
}
sealed class Store {
 public readonly string Root,StateRoot;public readonly object Gate=new object();
 public Store(string root){Root=Path.Combine(root,"documents");StateRoot=Path.Combine(root,"sync");Directory.CreateDirectory(Root);Directory.CreateDirectory(StateRoot);}
 public string Dir(string id){if(!J.ValidId(id))throw new Exception("Identificador de caderno inválido.");return Path.Combine(Root,id);}
 public Dictionary<string,object> Read(string id){var f=Path.Combine(Dir(id),"document.json");try{return J.Parse(File.ReadAllText(f,Encoding.UTF8));}catch{if(File.Exists(f+".bak"))return J.Parse(File.ReadAllText(f+".bak",Encoding.UTF8));throw;}}
 public static void Validate(Dictionary<string,object> d){if(J.I(d,"version")!=2||!J.ValidId(J.S(d,"id"))||J.I(d,"count")<1||J.I(d,"count")>10000)throw new Exception("Formato de caderno não suportado.");if(J.S(d,"name").Length>1000)throw new Exception("Nome muito longo.");KanaPages.Validate(d);var pages=J.Obj(d["pages"]);int total=0;foreach(var p in pages){int i;if(!int.TryParse(p.Key,out i)||i<0||i>=J.I(d,"count"))throw new Exception("Página inválida.");foreach(var o in J.List(p.Value)){var s=J.Obj(o);Glyphs.Validate(s);var kind=J.S(s,"kind","ink");if(kind!="ink"&&kind!="text"&&kind!="image")throw new Exception("Objeto inválido.");if(kind=="image"&&!System.Text.RegularExpressions.Regex.IsMatch(J.S(s,"asset"),@"^[a-fA-F0-9-]{36}\.(png|jpg|jpeg)$"))throw new Exception("Imagem inválida.");if(++total>500000)throw new Exception("Caderno muito grande.");foreach(var q in J.List(s["points"])){var a=J.List(q).ToArray();if(a.Length!=3||a.Any(v=>double.IsNaN(Convert.ToDouble(v))||double.IsInfinity(Convert.ToDouble(v))||Math.Abs(Convert.ToDouble(v))>10000000))throw new Exception("Traço inválido.");}}}}
 public void Write(Dictionary<string,object>d){Validate(d);var dir=Dir(J.S(d,"id"));var old=Path.Combine(dir,"document.json");if(File.Exists(old)&&Versions.Due(this,J.S(d,"id"))){var previous=Read(J.S(d,"id"));if(J.Fingerprint(previous)!=J.Fingerprint(d))Versions.Save(this,previous,false);}J.Atomic(Path.Combine(dir,"document.json"),J.Encode(d));var meta=new Dictionary<string,object>(d);meta.Remove("pages");meta["_localHash"]=J.Fingerprint(d);J.Atomic(Path.Combine(dir,"metadata.json"),J.Encode(meta));}
 public object[] Library(bool all=false){var result=new List<object>();foreach(var dir in Directory.GetDirectories(Root)){if(!J.ValidId(Path.GetFileName(dir)))continue;try{var f=Path.Combine(dir,"metadata.json");var d=File.Exists(f)?J.Parse(File.ReadAllText(f)):Read(Path.GetFileName(dir));d.Remove("pages");if(!d.ContainsKey("_localHash")){d["_localHash"]=J.Fingerprint(Read(Path.GetFileName(dir)));J.Atomic(f,J.Encode(d));}if(all||!IsDeleted(d))result.Add(d);}catch{}}return result.OrderByDescending(x=>Convert.ToInt64(J.Obj(x)["updated"])).ToArray();}
 public static bool IsDeleted(Dictionary<string,object> d){return d.ContainsKey("deleted")&&Convert.ToBoolean(d["deleted"]);}
 public void Trash(string id,bool deleted){var d=Read(id);if(deleted)d["deleted"]=true;else d.Remove("deleted");d["updated"]=J.Now();d["revision"]=J.Id();Write(d);}
 public Dictionary<string,object> Create(string name,string paper,bool persist=true){var d=J.Parse("{\"version\":2,\"pdf\":false,\"folder\":\"\",\"originId\":\"\",\"count\":1,\"lastPage\":0,\"bookmarks\":[],\"pages\":{}}");d["id"]=J.Id();d["revision"]=J.Id();d["name"]=name;d["paper"]=paper;d["updated"]=J.Now();KanaPages.Initialize(d);if(persist)Write(d);return d;}
 public string DataFile(string id,string rel){if(rel!="source.pdf"&&!System.Text.RegularExpressions.Regex.IsMatch(rel,@"^assets/[a-fA-F0-9-]{36}\.(png|jpg|jpeg)$"))throw new Exception("Arquivo inválido.");return Path.Combine(Dir(id),rel.Replace('/',Path.DirectorySeparatorChar));}
 public string ImportBackup(string file){var temp=Path.Combine(StateRoot,"import-"+J.Id());Directory.CreateDirectory(temp);try{long total=0;using(var zip=ZipFile.OpenRead(file)){var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);if(zip.Entries.Count>10002)throw new Exception("Backup com arquivos demais.");foreach(var e in zip.Entries){var n=e.FullName;if(n!="document.json"&&n!="source.pdf"&&!System.Text.RegularExpressions.Regex.IsMatch(n,@"^assets/[a-fA-F0-9-]{36}\.(png|jpg|jpeg)$"))throw new Exception("Arquivo inesperado no backup.");if(!seen.Add(n)||(total+=e.Length)>1024L*1024*1024||e.Length<0)throw new Exception("Backup excede os limites.");var dest=Path.Combine(temp,n.Replace('/',Path.DirectorySeparatorChar));Directory.CreateDirectory(Path.GetDirectoryName(dest));using(var input=e.Open())using(var output=File.Create(dest)){CopyBounded(input,output,e.Length);}}}var doc=J.Parse(File.ReadAllText(Path.Combine(temp,"document.json")));Validate(doc);var old=J.S(doc,"id");if(Directory.Exists(Dir(old))){doc["originId"]=old;doc["id"]=J.Id();doc["name"]=J.S(doc,"name")+" (cópia)";}var id=J.S(doc,"id");if(Convert.ToBoolean(doc["pdf"])&&!File.Exists(Path.Combine(temp,"source.pdf")))throw new Exception("PDF ausente.");Directory.Move(temp,Dir(id));Write(doc);return id;}finally{if(Directory.Exists(temp))Directory.Delete(temp,true);}}
 public void Backup(string id,string target){var dir=Dir(id);var tmp=target+".tmp";using(var z=ZipFile.Open(tmp,ZipArchiveMode.Create)){z.CreateEntryFromFile(Path.Combine(dir,"document.json"),"document.json",CompressionLevel.Optimal);if(File.Exists(Path.Combine(dir,"source.pdf")))z.CreateEntryFromFile(Path.Combine(dir,"source.pdf"),"source.pdf",CompressionLevel.NoCompression);var a=Path.Combine(dir,"assets");if(Directory.Exists(a))foreach(var f in Directory.GetFiles(a)){DataFile(id,"assets/"+Path.GetFileName(f));z.CreateEntryFromFile(f,"assets/"+Path.GetFileName(f),CompressionLevel.NoCompression);}}if(File.Exists(target))File.Delete(target);File.Move(tmp,target);}
 public static void CopyBounded(Stream src,Stream dst,long max){var b=new byte[65536];long total=0;int n;while((n=src.Read(b,0,b.Length))>0){total+=n;if(total>max)throw new Exception("Arquivo excede o limite.");dst.Write(b,0,n);}}
}
sealed class Window:Form {
 [System.Runtime.InteropServices.DllImport("dwmapi.dll")]static extern int DwmSetWindowAttribute(IntPtr hwnd,int attribute,ref int value,int size);
 readonly WebView2 view=new WebView2();readonly Store store;readonly SemaphoreSlim commands=new SemaphoreSlim(1,1);readonly string root;Cloud cloud;string openId="";bool closing,closeRequested;
 public Window(string data){root=data;store=new Store(data);Text="Folha · Espaço para pensar";MinimumSize=new Size(850,600);Size=new Size(1280,860);StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(247,246,242);view.Dock=DockStyle.Fill;Controls.Add(view);Load+=async(s,e)=>await Init();FormClosing+=(s,e)=>{if(!closing){e.Cancel=true;RequestClose();}};}
 void RequestClose(){if(closeRequested)return;if(view.CoreWebView2==null){closing=true;Close();return;}closeRequested=true;view.CoreWebView2.PostWebMessageAsJson(J.Encode(new{evt="closing"}));}
 async Task Init(){try{var env=await CoreWebView2Environment.CreateAsync(null,Path.Combine(root,"webview"));await view.EnsureCoreWebView2Async(env);var c=view.CoreWebView2;c.Settings.AreDevToolsEnabled=false;c.Settings.AreDefaultContextMenusEnabled=false;c.Settings.IsStatusBarEnabled=false;c.Settings.IsPasswordAutosaveEnabled=false;c.Settings.IsGeneralAutofillEnabled=false;c.SetVirtualHostNameToFolderMapping("folha.local",Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"web"),CoreWebView2HostResourceAccessKind.DenyCors);c.AddWebResourceRequestedFilter("https://folha-data.local/data/*",CoreWebView2WebResourceContext.All,CoreWebView2WebResourceRequestSourceKinds.All);c.WebResourceRequested+=Resource;c.NavigationStarting+=(s,e)=>{if(!e.Uri.StartsWith("https://folha.local/",StringComparison.Ordinal))e.Cancel=true;};c.NewWindowRequested+=(s,e)=>e.Handled=true;c.PermissionRequested+=(s,e)=>e.State=CoreWebView2PermissionState.Deny;c.WebMessageReceived+=Message;cloud=new Cloud(store,root,()=>openId,Notify);c.Navigate("https://folha.local/index.html");}catch(Exception e){MessageBox.Show("Não foi possível iniciar o Folha. Verifique se o Microsoft Edge WebView2 Runtime está instalado.\n\n"+e.Message,"Folha");closing=true;Close();}}
 void Resource(object sender,CoreWebView2WebResourceRequestedEventArgs e){try{var uri=new Uri(e.Request.Uri);if(uri.Scheme!="https"||uri.Host!="folha-data.local"||e.Request.Method!="GET")throw new Exception();var p=Uri.UnescapeDataString(uri.AbsolutePath).Split('/');if(p.Length<4||p[1]!="data")throw new Exception();var rel=string.Join("/",p.Skip(3));var f=store.DataFile(p[2],rel);var type=rel.EndsWith(".pdf")?"application/pdf":rel.EndsWith(".png")?"image/png":"image/jpeg";var stream=new FileStream(f,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete);e.Response=view.CoreWebView2.Environment.CreateWebResourceResponse(stream,200,"OK","Content-Type: "+type+"\r\nContent-Length: "+stream.Length+"\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nAccess-Control-Allow-Origin: https://folha.local");}catch{e.Response=view.CoreWebView2.Environment.CreateWebResourceResponse(null,404,"Not Found","");}}
 public void Notify(){if(IsDisposed)return;BeginInvoke(new Action(()=>{if(!IsDisposed&&view.CoreWebView2!=null)view.CoreWebView2.PostWebMessageAsJson(J.Encode(new{evt="cloud",data=cloud.Status()}));}));}
 async void Message(object sender,CoreWebView2WebMessageReceivedEventArgs e){if(e.Source!="https://folha.local/index.html")return;Dictionary<string,object> m;try{m=J.Parse(e.WebMessageAsJson);}catch{return;}if(m.ContainsKey("appearance")){bool dark=J.S(m,"appearance")=="dark";int useDark=dark?1:0;try{DwmSetWindowAttribute(Handle,20,ref useDark,sizeof(int));}catch{}return;}var id=J.S(m,"request");try{var command=J.S(m,"command");var p=m.ContainsKey("data")?J.Obj(m["data"]):new Dictionary<string,object>();object result;
 if(command=="closeApp"){closing=true;Close();return;}
 else if(command=="keepOpen"){closeRequested=false;result=true;}
 else if(command=="connect"){result=await cloud.Connect();}
 else if(command=="sync"){cloud.Start();result=cloud.Status();}
 else if(command=="disconnect"){await cloud.Disconnect();result=cloud.Status();}
 else if(command=="import"){result=await Import();}
 else if(command=="backup"){var save=new SaveFileDialog{Filter="Caderno Folha|*.folha",FileName="Caderno.folha"};if(save.ShowDialog(this)!=DialogResult.OK)result=null;else {await commands.WaitAsync();try{await Task.Run(()=>{lock(store.Gate)store.Backup(J.S(p,"id"),save.FileName);});result=true;}finally{commands.Release();}}}
 else if(command=="savePdf"){var save=new SaveFileDialog{Filter="Documento PDF|*.pdf",FileName="Anotações.pdf"};if(save.ShowDialog(this)!=DialogResult.OK)result=null;else{var bytes=Convert.FromBase64String(J.S(p,"bytes"));await Task.Run(()=>File.WriteAllBytes(save.FileName,bytes));result=true;}}
 else{await commands.WaitAsync();try{result=await Task.Run(()=>{lock(store.Gate)return Run(command,p);});}finally{commands.Release();}}
 view.CoreWebView2.PostWebMessageAsJson(J.Encode(new{request=id,result=result}));}catch(Exception err){if(!IsDisposed)view.CoreWebView2.PostWebMessageAsJson(J.Encode(new{request=id,error=err.Message}));}}
 object Run(string c,Dictionary<string,object> p){switch(c){case "init":return new{library=store.Library(true),cloud=cloud.Status(),version="0.8.3"};case "list":return store.Library(true);case "contentList":return ContentCatalog.List(store);case "contentAdd":{var d=ContentCatalog.Add(store,J.S(p,"id"));cloud.Edited(J.S(d,"id"));return d;}case "versions":return Versions.List(store,J.S(p,"id"));case "checkpoint":Versions.Save(store,store.Read(J.S(p,"id")),true);return true;case "restoreVersion":{var copy=Versions.Restore(store,J.S(p,"id"),J.S(p,"key"));cloud.Edited(copy);return copy;}case "libraryMeta":{var d=store.Read(J.S(p,"id"));foreach(var k in new[]{"favorite","cover","folder"})if(p.ContainsKey(k))d[k]=p[k];d["updated"]=J.Now();d["revision"]=J.Id();store.Write(d);cloud.Edited(J.S(d,"id"));return true;}case "trash":{var id=J.S(p,"id");if(openId==id)throw new Exception("Feche o arquivo antes de excluí-lo.");store.Trash(id,true);cloud.Edited();return true;}case "restore":store.Trash(J.S(p,"id"),false);cloud.Edited();return true;case "new":return store.Create(J.S(p,"name","Sem título"),J.S(p,"paper","lines"));case "open":{var d=store.Read(J.S(p,"id"));if(Store.IsDeleted(d))throw new Exception("Este arquivo está na lixeira. Restaure-o antes de abrir.");openId=J.S(p,"id");d["lastOpened"]=J.Now();store.Write(d);return d;}case "close":openId="";cloud.Edited();return true;case "patch":{var d=store.Read(J.S(p,"id"));DesktopEdits.Apply(d,p);d["updated"]=J.Now();d["revision"]=J.Id();store.Write(d);cloud.Edited(J.S(d,"id"));return true;}case "pdfCount":{var d=store.Read(J.S(p,"id"));d["count"]=J.I(p,"count");d.Remove("pdfPending");store.Write(d);cloud.Edited();return true;}default:throw new Exception("Comando indisponível.");}}
 async Task<object> Import(){var dialog=new OpenFileDialog{Filter="PDF ou caderno Folha|*.pdf;*.folha"};if(dialog.ShowDialog(this)!=DialogResult.OK)return null;var file=dialog.FileName;return await Task.Run(()=>{lock(store.Gate){if(file.EndsWith(".folha",StringComparison.OrdinalIgnoreCase)){var id=store.ImportBackup(file);cloud.Edited();return store.Read(id);}if(new FileInfo(file).Length>1024L*1024*1024)throw new Exception("PDF maior que 1 GB.");var d=store.Create(Path.GetFileNameWithoutExtension(file),"blank",false);d["pdf"]=true;d["pdfPending"]=true;try{File.Copy(file,Path.Combine(store.Dir(J.S(d,"id")),"source.pdf"));store.Write(d);cloud.Edited();return d;}catch{throw new Exception("Não foi possível importar o PDF.");}}});}
}
static class Program {
 [STAThread]static void Main(string[] args){ServiceSetup();if(args.Length==3&&args[0]=="--pdf-test"){PdfQa.Run(args[1],args[2]);return;}if(args.Contains("--self-test")){try{Tests.Run();Environment.ExitCode=0;}catch(Exception e){Console.WriteLine(e);Environment.ExitCode=1;}return;}var data=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Folha");Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);bool created;using(var mutex=new Mutex(true,"Local\\Folha-"+J.Hash(Encoding.UTF8.GetBytes(data)),out created)){if(!created||System.Diagnostics.Process.GetProcessesByName("Folha").Any(p=>p.Id!=System.Diagnostics.Process.GetCurrentProcess().Id&&p.SessionId==System.Diagnostics.Process.GetCurrentProcess().SessionId)){MessageBox.Show("O Folha já está aberto neste perfil do Windows.","Folha");return;}try{Application.Run(new Window(data));}finally{mutex.ReleaseMutex();}}}
 static void ServiceSetup(){System.Net.ServicePointManager.SecurityProtocol=System.Net.SecurityProtocolType.Tls12;}
}
